(function (Scratch) {
  // Made by ddededodediamante

  if (!Scratch.extensions.unsandboxed) {
    alert("Subway Surfers extension must run unsandboxed!");
    throw new Error("Subway Surfers extension must run unsandboxed");
  }

  const icon =
    "data:image/png;base64,";

  let dvdEnabled = false;
  let dvdSpeed = 2;
  let dvdVX = dvdSpeed;
  let dvdVY = dvdSpeed;

  class Extension {
    getInfo() {
      return {
        id: "ddeSubwaySurfers",
        name: "Subway Surfers",
        menuIconURI: icon,
        blockIconURI: icon,
        color1: "#737FFF",
        blocks: [
          {
            opcode: "setDVDBounce",
            blockType: Scratch.BlockType.COMMAND,
            text: "set DVD bounce to [STATE]",
            arguments: {
              STATE: {
                type: Scratch.ArgumentType.STRING,
                menu: "onOffMenu",
              },
            },
          },
          {
            opcode: "setDVDSpeed",
            blockType: Scratch.BlockType.COMMAND,
            text: "set DVD speed to [SPEED]",
            arguments: {
              SPEED: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 2,
              },
            },
          },
        ],
        menus: {
          onOffMenu: {
            acceptReporters: true,
            items: ["true", "false"],
          },
        },
      };
    }

    setDVDBounce({ STATE }) {
      dvdEnabled = Scratch.Cast.toBoolean(STATE);
    }

    setDVDSpeed({ SPEED }) {
      const speed = Scratch.Cast.toNumber(SPEED);

      dvdSpeed = Math.max(0, speed);
      dvdVX = dvdVX >= 0 ? dvdSpeed : -dvdSpeed;
      dvdVY = dvdVY >= 0 ? dvdSpeed : -dvdSpeed;
    }
  }

  const video = document.createElement("video");

  const loading = document.createElement("div");
  loading.innerText = "Loading video...";
  loading.style.position = "fixed";
  loading.style.top = "50%";
  loading.style.left = "50%";
  loading.style.transform = "translate(-50%, -50%)";
  loading.style.padding = "10px";
  loading.style.background = "rgba(0, 0, 0, 0.5)";
  loading.style.color = "white";
  loading.style.fontSize = "20px";
  loading.style.zIndex = String(5e10);
  document.body.appendChild(loading);

  video.src = "https://files.catbox.moe/go1vik.mp4";
  video.autoplay = true;
  video.loop = true;
  video.style.position = "fixed";
  video.style.zIndex = String(5e10);
  video.style.width = "30%";
  video.style.height = "auto";
  video.style.pointerEvents = "none";
  document.body.appendChild(video);

  video.addEventListener("loadstart", () => {
    loading.style.display = "block";
  });

  video.addEventListener("waiting", () => {
    loading.style.display = "block";
  });

  video.addEventListener("canplay", () => {
    loading.style.display = "none";
  });

  video.addEventListener("playing", () => {
    loading.style.display = "none";
  });

  function moveRandomly() {
    video.style.left = `${Math.floor(
      Math.random() * (window.innerWidth - video.offsetWidth)
    )}px`;
    video.style.top = `${Math.floor(
      Math.random() * (window.innerHeight - video.offsetHeight)
    )}px`;
  }

  video.addEventListener("mouseenter", () => {
    if (!dvdEnabled) moveRandomly();
  });

  const move = () => {
    if (!dvdEnabled) {
      moveRandomly();
    }
    setTimeout(
      move,
      Math.floor(Math.random() * (25_000 - 15_000 + 1)) + 15_000
    );
  };
  move();

  function dvdLoop() {
    if (dvdEnabled) {
      let x = parseFloat(video.style.left || 0);
      let y = parseFloat(video.style.top || 0);

      x += dvdVX;
      y += dvdVY;

      if (x <= 0 || x + video.offsetWidth >= window.innerWidth) {
        dvdVX *= -1;
      }

      if (y <= 0 || y + video.offsetHeight >= window.innerHeight) {
        dvdVY *= -1;
      }

      video.style.left = `${x}px`;
      video.style.top = `${y}px`;
    }

    requestAnimationFrame(dvdLoop);
  }
  dvdLoop();

  Scratch.extensions.register(new Extension());
})(Scratch);
